<p class="eyebrow">Support</p><h1>Contact messages</h1><div class="table-wrap"><table><thead><tr><th>From</th><th>Country</th><th>Subject</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($messages as $message):?><tr><td><?= e($message['name']) ?><br><small><?= e($message['email']) ?></small></td><td><?= e($message['country_name']) ?></td><td><?= e($message['subject']) ?><br><small><?= e(mb_strimwidth($message['message'],0,100,'…')) ?></small></td><td><?= e($message['status']) ?></td><td><?= e($message['created_at']) ?></td><td><form method="post" action="<?= e(route('admin.contact-messages.status',['message'=>$message['id']])) ?>"><?= app('csrf')->input() ?><select name="status"><option>read</option><option>resolved</option><option>archived</option><option>unread</option></select><button class="text-button">Save</button></form></td></tr><?php endforeach;?></tbody></table></div>
